def apply(inputs, premises):
    total = int(inputs["ticket_price"])
    carry_used = False
    checked_index = 0
    bag_count = len(inputs["bag_lengths"])
    for i in range(bag_count):
        carry_ok = inputs["bag_lengths"][i] <= inputs["carry_on_dimension_limits"][0] and inputs["bag_widths"][i] <= inputs["carry_on_dimension_limits"][1] and inputs["bag_heights"][i] <= inputs["carry_on_dimension_limits"][2]
        if carry_ok and not carry_used:
            carry_used = True
        else:
            fee_index = checked_index
            if fee_index >= len(inputs["checked_bag_fees"]):
                fee_index = len(inputs["checked_bag_fees"]) - 1
            checked_fee = int(inputs["checked_bag_fees"][fee_index])
            weight = inputs["bag_weights"][i]
            overweight_fee = 0
            if weight > inputs["overweight_upper_bounds"][0] and weight <= inputs["overweight_upper_bounds"][1]:
                overweight_fee = int(inputs["overweight_band_fees"][0])
            if weight > inputs["overweight_upper_bounds"][1] and weight <= inputs["overweight_upper_bounds"][2]:
                overweight_fee = int(inputs["overweight_band_fees"][1])
            if weight > inputs["overweight_upper_bounds"][2] and weight <= inputs["overweight_upper_bounds"][3]:
                overweight_fee = int(inputs["overweight_band_fees"][2])
            dimension_total = inputs["bag_lengths"][i] + inputs["bag_widths"][i] + inputs["bag_heights"][i]
            oversize_fee = 0
            if dimension_total > inputs["oversize_upper_bounds"][0] and dimension_total <= inputs["oversize_upper_bounds"][1]:
                oversize_fee = int(inputs["oversize_band_fees"][0])
            if dimension_total > inputs["oversize_upper_bounds"][1] and dimension_total <= inputs["oversize_upper_bounds"][2]:
                oversize_fee = int(inputs["oversize_band_fees"][1])
            total = total + checked_fee + max(overweight_fee, oversize_fee)
            checked_index = checked_index + 1
    return {"answer": int(total)}

